styl:
.iq-cta-button--iq-cta-button{max-width:{{ max_width }}px;width:100%}
@media screen and (max-width:600px){.iq-cta-button--iq-cta-button{max-width:100%!important}}
.iq-cta-button--iq-cta-cell{background-color:{{ background_color }};background-size:cover;border:{{ border }};border-radius:{{ radius }}!important;font-family:Helvetica,Arial,sans-serif!important;font-size:18px!important;font-weight:700!important;height:auto}
.iq-cta-button--iq-cta-link{color:{{ text_color }};display:block;font-size:18px;font-weight:700;letter-spacing:0;line-height:27px;padding:{{ padding }};text-align:center;text-decoration:none;text-transform:none}
